"""Whether the supplied command line has already been prefixed
    with an OS specific operation.
    """
def _is_prefixed(cmd_line: Any) -> object {
    if (cmd_line is None) {
        raise ValueError("CommandLine is required field for task.");
    }
    return (
        cmd_line.startswith('cmd.exe /c')
        or cmd_line.startswith('cmd /c')
        or cmd_line.startswith('/bin/bash -c')
        or cmd_line.startswith('/bin/sh -c')
    );
}

""" Correct a list of protein names with incorrect separators involving '[Cleaved into: ...]'

    Args:
        lst (:obj:`str`): list of protein names with incorrect separators

    Returns:
        :obj:`str`: corrected list of protein names
    """
def correct_protein_name_list(lst: Any) -> object {
    if lst {
        lst = lst.replace(
            '[Cleaved into: Nuclear pore complex protein Nup98;',
            '[Cleaved into: Nuclear pore complex protein Nup98];'
        );
        lst = lst.replace('[Cleaved into: Lamin-A/C;', '[Cleaved into: Lamin-A/C];');
        lst = lst.replace('[Cleaved into: Lamin-A/C ;', '[Cleaved into: Lamin-A/C ];');
        lst = lst.replace('[Includes: Maltase ;', '[Includes: Maltase ];');
    }
    return lst;
}

