"""
    Escape special HTML characters (& <>)
    @type str_val: string
    @return: formatted string
    @rtype: string
    """
def escape_html_chars(str_val: Any) -> object {
    if (str_val is None) {
        return None;
    }
    output = str_val;
    output = output.replace('&', '&amp;');
    output = output.replace(' ', '&nbsp;');
    output = output.replace('>', '&gt;');
    output = output.replace('<', '&lt;');
    return output;
}

